$b18herbs = [
    ['name' => 'Bai Fan', 'latin' => 'Alumen', 'meta' => $b18text('Sour, astringent, cold · Large Intestine, Liver, Lung, Spleen · 1–3 g decocted', 'Ácida, astringente, fría · Intestino Grueso, Hígado, Pulmón, Bazo · 1–3 g en decocción'), 'focus' => $b18text('Externally dries Dampness, resolves toxicity, kills parasites, stops itching and bleeding; internally transforms phlegm and restrains chronic diarrhea.', 'Externamente seca Humedad, resuelve toxicidad, elimina parásitos, detiene prurito y sangrado; internamente transforma Flema y restringe diarrea crónica.'), 'clue' => $b18text('Weeping, itchy lesions, genital discharge or chronic nonhealing sores requiring a drying astringent.', 'Lesiones exudativas y pruriginosas, flujo genital o llagas crónicas que requieren un astringente secante.'), 'safety' => $b18text('Internal use may cause nausea, vomiting, gastrointestinal injury, hematuria and electrolyte toxicity. Avoid weak digestion and absence of Damp-Heat.', 'Uso interno puede causar náusea, vómito, lesión gastrointestinal, hematuria y toxicidad electrolítica. Evitar digestión débil y ausencia de Calor-Humedad.'), 'preparation' => $b18text('Calcined/dehydrated alum is less emetic and more strongly restrains sores, bleeding and seepage.', 'El alumbre calcinado/deshidratado es menos emético y restringe con más fuerza llagas, sangrado y exudación.'), 'official' => false],
    ['name' => 'Lu Gan Shi', 'latin' => 'Calamina', 'meta' => $b18text('Sweet, neutral · Liver, Stomach · external use only', 'Dulce, neutra · Hígado, Estómago · solo uso externo'), 'focus' => $b18text('Brightens the eyes, removes superficial visual obstructions, dries Dampness and promotes healing of chronically draining sores.', 'Aclara los ojos, elimina obstrucciones visuales superficiales, seca Humedad y favorece curación de llagas con exudación crónica.'), 'clue' => $b18text('Red, swollen or tearing eyes, pterygium, or a nonhealing Damp sore needing a mild nonirritating mineral.', 'Ojos rojos, hinchados o lagrimosos, pterigión o llaga húmeda que no cicatriza y requiere mineral suave no irritante.'), 'safety' => $b18text('Do not take internally. Use only as a properly prepared fine powder.', 'No ingerir. Usar únicamente como polvo fino correctamente preparado.'), 'preparation' => $b18text('Repeated calcining and aqueous trituration produce the fine ophthalmic powder; Coptis preparation strengthens Heat-clearing.', 'Calcinación repetida y trituración acuosa producen el polvo oftálmico fino; preparación con Coptis refuerza aclarar Calor.'), 'official' => false],
    ['name' => 'Liu Huang', 'latin' => 'Sulfur', 'meta' => $b18text('Sour, hot, toxic · Kidney, Large Intestine, Pericardium · 1–3 g', 'Ácida, caliente, tóxica · Riñón, Intestino Grueso, Pericardio · 1–3 g'), 'focus' => $b18text('Externally kills parasites, resolves toxicity and stops itching in scabies, tinea and recalcitrant sores; processed form tonifies Kidney fire internally.', 'Externamente elimina parásitos, resuelve toxicidad y detiene prurito en sarna, tiña y llagas resistentes; procesada tonifica Fuego de Riñón internamente.'), 'clue' => $b18text('Scabies or tinea with intense itching; processed sulfur only when internal cold from Kidney-yang deficiency is clearly established.', 'Sarna o tiña con prurito intenso; azufre procesado solo cuando se establece claramente Frío interno por deficiencia de Yang de Riñón.'), 'safety' => $b18text('Toxic in high oral doses. Contraindicated in pregnancy and yin-deficiency Heat; internal use requires processed material and professional control.', 'Tóxica en dosis orales altas. Contraindicada en embarazo y Calor por deficiencia de yin; uso interno exige material procesado y control profesional.'), 'preparation' => $b18text('Raw sulfur is primarily external; bean-curd processing reduces odor and toxicity for internal pill use.', 'Azufre crudo es principalmente externo; procesarlo con tofu reduce olor y toxicidad para uso interno en píldoras.'), 'official' => true],
    ['name' => 'Qian Dan', 'latin' => 'Minium', 'meta' => $b18text('Acrid, cool, toxic · Heart, Liver, Spleen · 0.3–0.6 g', 'Acre, fresca, tóxica · Corazón, Hígado, Bazo · 0.3–0.6 g'), 'focus' => $b18text('A lead-oxide mineral used externally to uproot toxicity, generate flesh, dry Dampness and stop itching in toxic or nonhealing sores.', 'Mineral de óxido de plomo usado externamente para arrancar toxicidad, generar carne, secar Humedad y detener prurito en llagas tóxicas o que no cicatrizan.'), 'clue' => $b18text('A toxic abscess or chronic ulcer requiring an ingredient in a traditional plaster—not an internal remedy.', 'Absceso tóxico o úlcera crónica que requiere ingrediente de emplasto tradicional, no remedio interno.'), 'safety' => $b18text('Lead poisoning can be fatal and accumulates with small repeated doses. Internal use is no longer generally recommended.', 'Intoxicación por plomo puede ser mortal y acumularse con dosis pequeñas repetidas. Uso interno ya no se recomienda generalmente.'), 'preparation' => $b18text('Identity is red lead oxide (Pb3O4); color varies with processing and provenance.', 'La identidad es óxido rojo de plomo (Pb3O4); color varía según procesamiento y procedencia.'), 'official' => false],
    ['name' => 'She Chuang Zi', 'latin' => 'Cnidii Fructus', 'meta' => $b18text('Acrid, bitter, warm, slightly toxic · Kidney · 3–9 g', 'Acre, amarga, tibia, ligeramente tóxica · Riñón · 3–9 g'), 'focus' => $b18text('Externally dries Dampness, kills parasites and stops genital or skin itching; internally warms the Kidneys and fortifies yang.', 'Externamente seca Humedad, elimina parásitos y detiene prurito genital o cutáneo; internamente calienta Riñones y fortalece Yang.'), 'clue' => $b18text('Weeping genital itching, scabies or tinea with Cold-Dampness; impotence or infertility from Kidney cold when used internally.', 'Prurito genital exudativo, sarna o tiña con Frío-Humedad; impotencia o infertilidad por Frío de Riñón cuando se usa internamente.'), 'safety' => $b18text('Avoid oral use in lower-burner Damp-Heat or yin-deficiency Heat. Topical combinations can provoke erythema and severe itching.', 'Evitar uso oral en Calor-Humedad del Jiao inferior o Calor por deficiencia de yin. Combinaciones tópicas pueden provocar eritema y prurito intenso.'), 'preparation' => $b18text('Use raw for washes; traditional internal preparation removes the husk and lightly dry-fries the kernels.', 'Usar cruda para lavados; preparación interna tradicional retira cáscara y tuesta ligeramente los núcleos.'), 'official' => true],
    ['name' => 'Tu Jing Pi', 'latin' => 'Pseudolaricis Cortex', 'meta' => $b18text('Acrid, warm, toxic · Lung, Spleen · external use only', 'Acre, tibia, tóxica · Pulmón, Bazo · solo uso externo'), 'focus' => $b18text('A strong external antifungal and antipruritic bark for tinea, eczema, scabies and other Wind-Damp skin disorders.', 'Corteza antifúngica y antipruriginosa fuerte de uso externo para tiña, eczema, sarna y otros trastornos cutáneos de Viento-Humedad.'), 'clue' => $b18text('Stubborn tinea or itching treated with a vinegar plaster or tincture.', 'Tiña resistente o prurito tratado con emplasto de vinagre o tintura.'), 'safety' => $b18text('Toxic and strictly external. Ingestion may severely irritate the gastrointestinal mucosa.', 'Tóxica y estrictamente externa. Ingestión puede irritar gravemente la mucosa gastrointestinal.'), 'preparation' => $b18text('Verify golden-larch root bark; the trade name is easily confused with unrelated bark names.', 'Verificar corteza de raíz de alerce dorado; el nombre comercial se confunde fácilmente con cortezas no relacionadas.'), 'official' => false],
    ['name' => 'Mu Bie Zi', 'latin' => 'Momordicae Semen', 'meta' => $b18text('Bitter, slightly sweet, warm, toxic · Large Intestine, Liver, Stomach · 0.9–1.2 g', 'Amarga, ligeramente dulce, tibia, tóxica · Intestino Grueso, Hígado, Estómago · 0.9–1.2 g'), 'focus' => $b18text('Reduces swelling, disperses clumps, expels toxins and invigorates Blood for abscesses, scrofula and traumatic swelling.', 'Reduce hinchazón, dispersa masas, expulsa toxinas y vigoriza Sangre para abscesos, escrófula e hinchazón traumática.'), 'clue' => $b18text('A deep, hot, painful swelling or traumatic clump requiring topical dispersion.', 'Hinchazón profunda, caliente y dolorosa o masa traumática que requiere dispersión tópica.'), 'safety' => $b18text('Raw seed is toxic and mainly topical; ingestion or overdose may cause severe gastrointestinal, neurologic and circulatory toxicity. Avoid pregnancy and weakness.', 'Semilla cruda es tóxica y principalmente tópica; ingestión o sobredosis puede causar toxicidad gastrointestinal, neurológica y circulatoria grave. Evitar embarazo y debilidad.'), 'preparation' => $b18text('Only defatted “frost” is suitable for carefully controlled internal use.', 'Solo la “escarcha” desgrasada es apta para uso interno cuidadosamente controlado.'), 'official' => false],
    ['name' => 'Da Feng Zi', 'latin' => 'Hydnocarpi Semen', 'meta' => $b18text('Acrid, hot, toxic · Kidney, Liver, Spleen · 0.3–1 g', 'Acre, caliente, tóxica · Riñón, Hígado, Bazo · 0.3–1 g'), 'focus' => $b18text('Specific external seed for leprosy, scabies and tinea: expels Wind, dries Dampness, attacks toxins and kills parasites.', 'Semilla externa específica para lepra, sarna y tiña: expulsa Viento, seca Humedad, ataca toxinas y elimina parásitos.'), 'clue' => $b18text('Chronic parasitic or fungal skin disease historically treated with chaulmoogra oil.', 'Enfermedad cutánea parasitaria o fúngica crónica tratada históricamente con aceite de chaulmoogra.'), 'safety' => $b18text('Toxic when ingested; avoid pregnancy, yin-deficiency Heat, liver/kidney compromise, overdose and long-term use.', 'Tóxica al ingerirse; evitar embarazo, Calor por deficiencia de yin, compromiso hepatorrenal, sobredosis y uso prolongado.'), 'preparation' => $b18text('Expressing the oil produces a less toxic defatted powder, but does not make casual internal use safe.', 'Extraer el aceite produce polvo desgrasado menos tóxico, pero no vuelve seguro el uso interno casual.'), 'official' => false],
    ['name' => 'Er Cha', 'latin' => 'Catechu', 'meta' => $b18text('Bitter, astringent, slightly cold · Lung · 1–3 g', 'Amarga, astringente, ligeramente fría · Pulmón · 1–3 g'), 'focus' => $b18text('Externally absorbs seepage, closes nonhealing sores, moderates pain and stops bleeding; rare internal use clears Lung Heat and transforms phlegm.', 'Externamente absorbe exudación, cierra llagas que no cicatrizan, modera dolor y detiene sangrado; uso interno raro aclara Calor de Pulmón y transforma Flema.'), 'clue' => $b18text('Purulent, oozing chronic sore or traumatic bleeding requiring a transforming astringent.', 'Llaga crónica purulenta y exudativa o sangrado traumático que requiere astringente transformador.'), 'safety' => $b18text('Internal use is now rare. Verify black catechu versus regional brown/pale catechu products.', 'Uso interno ahora es raro. Verificar catechu negro frente a productos regionales marrón/pálido.'), 'preparation' => $b18text('A dried concentrated Acacia decoction; use a separate cloth bag if decocted.', 'Decocción concentrada y seca de Acacia; usar bolsa de tela separada si se decocta.'), 'official' => false],
    ['name' => 'Zhang Nao', 'latin' => 'Camphora', 'meta' => $b18text('Acrid, hot, toxic · Heart, Spleen · 0.1–0.2 g', 'Acre, caliente, tóxica · Corazón, Bazo · 0.1–0.2 g'), 'focus' => $b18text('Expels Wind and turbidity, kills parasites and relieves pain; externally used for scabies, tinea, trauma and toothache.', 'Expulsa Viento y turbidez, elimina parásitos y alivia dolor; uso externo para sarna, tiña, trauma y dolor dental.'), 'clue' => $b18text('A penetrating aromatic for itching or traumatic pain with Blood stasis, rather than a primary Damp-drying seed.', 'Aromático penetrante para prurito o dolor traumático con estasis de Sangre, no semilla secante de Humedad primaria.'), 'safety' => $b18text('Highly toxic if ingested or absorbed in concentrated topical products. Contraindicated in pregnancy and infants; caution in children.', 'Muy tóxica si se ingiere o absorbe en productos tópicos concentrados. Contraindicada en embarazo y lactantes; cautela en niños.'), 'preparation' => $b18text('Use clean white translucent crystals from verified camphor; avoid confusion with Borneolum.', 'Usar cristales blancos translúcidos limpios de alcanfor verificado; evitar confusión con Borneolum.'), 'official' => false],
    ['name' => 'Ban Mao', 'latin' => 'Mylabris', 'meta' => $b18text('Acrid, cold, highly toxic · Large Intestine, Liver, Stomach · 0.03–0.06 g', 'Acre, fría, muy tóxica · Intestino Grueso, Hígado, Estómago · 0.03–0.06 g'), 'focus' => $b18text('A blistering cantharides product that attacks toxic sores and breaks Blood stasis and fixed masses.', 'Producto vesicante de cantáridas que ataca llagas tóxicas y rompe estasis de Sangre y masas fijas.'), 'clue' => $b18text('Traditional external destruction of a toxic sore by deliberate severe irritation—not routine dermatologic use.', 'Destrucción externa tradicional de llaga tóxica mediante irritación intensa deliberada, no uso dermatológico rutinario.'), 'safety' => $b18text('Extremely toxic by ingestion, inhalation or excessive topical exposure; may cause hemorrhage, renal failure, shock and death. Contraindicated in pregnancy.', 'Extremadamente tóxica por ingestión, inhalación o exposición tópica excesiva; puede causar hemorragia, falla renal, choque y muerte. Contraindicada en embarazo.'), 'preparation' => $b18text('Rice processing reduces but does not eliminate cantharidin toxicity; professional handling is essential.', 'Procesamiento con arroz reduce pero no elimina toxicidad por cantaridina; manejo profesional es esencial.'), 'official' => false],
    ['name' => 'Chan Su', 'latin' => 'Bufonis Venenum', 'meta' => $b18text('Sweet, acrid, warm, toxic · Heart, Stomach · 0.01–0.03 g', 'Dulce, acre, tibia, tóxica · Corazón, Estómago · 0.01–0.03 g'), 'focus' => $b18text('Rapidly resolves toxicity, reduces swelling and pain, and opens the Heart orifices; used in specialized preparations for severe sores or loss of consciousness.', 'Resuelve rápidamente toxicidad, reduce hinchazón y dolor y abre orificios del Corazón; usada en preparados especializados para llagas graves o pérdida de conciencia.'), 'clue' => $b18text('A minute-dose emergency toxin for severe swelling or turbid closure—not a stand-alone home remedy.', 'Toxina de dosis mínima para emergencia con hinchazón grave o cierre por turbidez, no remedio casero independiente.'), 'safety' => $b18text('Cardiotoxic. Overdose may cause violent vomiting, arrhythmia, AV block, convulsions and shock. Avoid pregnancy, eyes and unapproved internal use.', 'Cardiotóxica. Sobredosis puede causar vómito violento, arritmia, bloqueo AV, convulsiones y choque. Evitar embarazo, ojos y uso interno no aprobado.'), 'preparation' => $b18text('Use only standardized, authority-approved preparations; metal contact and poor storage degrade the product.', 'Usar solo preparados estandarizados aprobados por autoridad; contacto con metal y almacenamiento deficiente degradan el producto.'), 'official' => false],
    ['name' => 'Feng Fang', 'latin' => 'Vespae Nidus', 'meta' => $b18text('Sweet, neutral, toxic · Lung, Stomach · 3–6 g as gargle', 'Dulce, neutra, tóxica · Pulmón, Estómago · 3–6 g como gárgara'), 'focus' => $b18text('Externally resolves toxicity, expels Wind, kills parasites and relieves pain in sores, scabies, tinea and severe toothache.', 'Externamente resuelve toxicidad, expulsa Viento, elimina parásitos y alivia dolor en llagas, sarna, tiña y dolor dental intenso.'), 'clue' => $b18text('Wind-Damp itching or severe “worm-burrowing” toothache treated with a wash, ointment or gargle.', 'Prurito por Viento-Humedad o dolor dental intenso “como gusano” tratado con lavado, ungüento o gárgara.'), 'safety' => $b18text('Gargle must never be swallowed. Avoid burst sores, impaired renal function and qi/Blood deficiency; volatile oils may cause nephritis.', 'La gárgara nunca debe tragarse. Evitar llagas abiertas, función renal deteriorada y deficiencia de Qi/Sangre; aceites volátiles pueden causar nefritis.'), 'preparation' => $b18text('Clean steamed nest is standard; calcining reduces toxicity and facilitates powder or plaster use.', 'Nido limpio al vapor es estándar; calcinar reduce toxicidad y facilita uso en polvo o emplasto.'), 'official' => false],
];

$b18officialherbs = array_values(array_filter($b18herbs, static function(array $herb): bool { return $herb['official']; }));
