    <div class="single-herbs-guide__pattern">
        <article><strong><?php echo s($b18text('Damp itching / parasites', 'Prurito húmedo / parásitos')); ?></strong><span>Liu Huang · She Chuang Zi · Tu Jing Pi · Da Feng Zi</span></article>
        <article><strong><?php echo s($b18text('Drainage / nonhealing sores', 'Exudación / llagas crónicas')); ?></strong><span>Bai Fan · Lu Gan Shi · Er Cha</span></article>
        <article><strong><?php echo s($b18text('Toxic swelling / clumps', 'Hinchazón tóxica / masas')); ?></strong><span>Mu Bie Zi · Qian Dan · Ban Mao · Chan Su</span></article>
        <article><strong><?php echo s($b18text('Pain / Wind / turbidity', 'Dolor / Viento / turbidez')); ?></strong><span>Zhang Nao · Feng Fang</span></article>
    </div>
    <aside class="single-herbs-guide__safety"><strong><?php echo s($b18text('Category caution', 'Precaución de la categoría')); ?></strong> <?php echo s($b18text('Topical use can still cause systemic poisoning through skin absorption, inhalation, mucosal contact or accidental ingestion. Ban Mao, Chan Su, Qian Dan, Zhang Nao and other toxic entries require specialized handling and are not self-care substances.', 'Uso tópico todavía puede causar intoxicación sistémica por absorción cutánea, inhalación, contacto mucoso o ingestión accidental. Ban Mao, Chan Su, Qian Dan, Zhang Nao y otras entradas tóxicas requieren manejo especializado y no son sustancias de autocuidado.')); ?></aside>
</section>

