<section class="single-herbs-guide__section" aria-labelledby="bensky-eighteen-comparisons">
    <h4 id="bensky-eighteen-comparisons"><?php echo s($b18text('High-yield comparisons', 'Comparaciones de alto rendimiento')); ?></h4>
    <div class="single-herbs-guide__decision">
        <div><strong>Bai Fan vs. Er Cha</strong><span><?php echo s($b18text('Bai Fan dries, restrains and kills parasites; Er Cha more specifically transforms purulent seepage and stops traumatic bleeding.', 'Bai Fan seca, restringe y elimina parásitos; Er Cha transforma más específicamente exudación purulenta y detiene sangrado traumático.')); ?></span></div>
        <div><strong>She Chuang Zi vs. Zhang Nao</strong><span><?php echo s($b18text('Warm Damp-drying genital antipruritic vs. penetrating aromatic for Wind, turbidity and traumatic pain.', 'Antipruriginosa genital tibia que seca Humedad vs. aromático penetrante para Viento, turbidez y dolor traumático.')); ?></span></div>
        <div><strong>Lu Gan Shi vs. Bai Fan</strong><span><?php echo s($b18text('Mild eye and healing mineral vs. stronger sour astringent for seepage, itching and bleeding.', 'Mineral suave para ojos y cicatrización vs. astringente ácido más fuerte para exudación, prurito y sangrado.')); ?></span></div>
        <div><strong>Mu Bie Zi vs. Ban Mao</strong><span><?php echo s($b18text('Disperses deep swelling and Blood stasis vs. deliberately blisters and wears away toxic tissue.', 'Dispersa hinchazón profunda y estasis de Sangre vs. produce ampollas deliberadamente y erosiona tejido tóxico.')); ?></span></div>
        <div><strong>Chan Su vs. Feng Fang</strong><span><?php echo s($b18text('Minute-dose cardiotoxic emergency substance vs. toxic wasp nest used mainly as wash, ointment or gargle.', 'Sustancia cardiotóxica de dosis mínima para emergencia vs. nido de avispa tóxico usado principalmente como lavado, ungüento o gárgara.')); ?></span></div>
    </div>
</section>

<section class="single-herbs-guide__section" aria-labelledby="bensky-eighteen-safety">
    <h4 id="bensky-eighteen-safety"><?php echo s($b18text('High-priority safety and identity traps', 'Seguridad prioritaria y trampas de identidad')); ?></h4>
    <div class="single-herbs-guide__safety">
        <strong><?php echo s($b18text('Systemic toxicity from external exposure', 'Toxicidad sistémica por exposición externa')); ?></strong><p><?php echo s($b18text('Camphor can be absorbed through skin; Mylabris powder can poison by inhalation or topical overdose; Chan Su can enter the eyes or circulation; Feng Fang volatile oils may injure the kidneys.', 'Alcanfor puede absorberse por piel; polvo de Mylabris puede intoxicar por inhalación o sobredosis tópica; Chan Su puede entrar en ojos o circulación; aceites volátiles de Feng Fang pueden lesionar riñones.')); ?></p>
        <strong><?php echo s($b18text('Preparation is part of identity', 'La preparación forma parte de la identidad')); ?></strong><p><?php echo s($b18text('Calcining changes Bai Fan and Lu Gan Shi; raw versus processed Liu Huang changes route and toxicity; defatting changes Mu Bie Zi and Da Feng Zi; rice-processing does not make Ban Mao broadly safe.', 'Calcinar cambia Bai Fan y Lu Gan Shi; Liu Huang cruda vs. procesada cambia vía y toxicidad; desgrasar cambia Mu Bie Zi y Da Feng Zi; procesar Ban Mao con arroz no la vuelve ampliamente segura.')); ?></p>
        <strong><?php echo s($b18text('Pregnancy and vulnerable patients', 'Embarazo y pacientes vulnerables')); ?></strong><p><?php echo s($b18text('Liu Huang, Mu Bie Zi, Da Feng Zi, Zhang Nao, Ban Mao and Chan Su are contraindicated or high-risk in pregnancy. Infants, children and patients with renal, hepatic, cardiac or mucosal vulnerability require special protection.', 'Liu Huang, Mu Bie Zi, Da Feng Zi, Zhang Nao, Ban Mao y Chan Su están contraindicadas o son de alto riesgo en embarazo. Lactantes, niños y pacientes con vulnerabilidad renal, hepática, cardíaca o mucosa requieren protección especial.')); ?></p>
    </div>
</section>

